insert into public.topics (name, name_pt, slug, description, description_pt, icon, sort_order) values ('Clinical Research', 'Pesquisa Clínica', 'clinical-research', 'Trial design, phases, endpoints and how evidence about medicines is generated in people.', 'Desenho de ensaios, fases, desfechos e como a evidência sobre medicamentos é gerada em pessoas.', 'clipboard-list', 1) on conflict (slug) do nothing;
