values (1, 'Fernando Osman', 'Pharmacy Student', array['Clinical Research', 'Medical Affairs', 'Data Analysis']::text[], 'Scientific communication, clinical evidence and data-driven learning in pharmacy.', 'I am a pharmacy student interested in how clinical evidence is generated, appraised and communicated.

This site collects my study notes on clinical research and biostatistics, structured reviews of clinical papers and small data projects. Writing about a concept is how I check that I actually understand it.

I am looking for opportunities in clinical research, medical affairs and evidence generation within the pharmaceutical industry.', 'Pharmacy', '', 6, 10, 'Brazil', '[{"name":"Portuguese","level":"Native"},{"name":"English","level":"Advanced"}]'::jsonb, array['Clinical Research', 'Medical Affairs', 'Biostatistics', 'Evidence-Based Medicine', 'Pharmacology', 'Health Data Analysis']::text[], '[{"institution":"University (edit in /admin/profile)","degree":"Bachelor of Pharmacy","start":"2023","end":"Expected 2028","description":"Coursework in pharmacology, pharmacokinetics, biostatistics and clinical pharmacy."}]'::jsonb, '[]'::jsonb, '[{"group":"Clinical evidence","items":["Critical appraisal","CONSORT","ICH-GCP fundamentals","Scientific writing"]},{"group":"Data","items":["R","Python (pandas)","Power BI","SQL"]},{"group":"Statistics","items":["Survival analysis","Confidence intervals","Regression"]}]'::jsonb, '[]'::jsonb)
on conflict (id) do nothing;

