values ('How Clinical Trials Work: Phase I, II, III and IV', 'how-clinical-trials-work-phase-i-ii-iii-and-iv', 'From first-in-human dosing to post-marketing surveillance', 'A practical walkthrough of the clinical development pathway: what each phase is designed to answer, typical sample sizes, and why most candidate drugs never reach patients.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why this matters"}]},{"type":"paragraph","content":[{"type":"text","text":"Every medicine dispensed in a pharmacy went through a sequence of studies designed to answer increasingly demanding questions: is it safe enough to give to people, does it seem to work, does it work better than what we already have, and what happens once millions of patients use it? Understanding this sequence is the starting point for reading any clinical paper."}]},{"type":"paragraph","content":[{"type":"text","text":"International guidance such as ICH E8(R1) describes development as a series of studies with distinct objectives rather than a rigid ladder "},{"type":"citation","attrs":{"refs":"1"}},{"type":"text","text":". The classic phase labels are still the vocabulary used by sponsors, regulators and journals."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Before humans: preclinical development"}]},{"type":"paragraph","content":[{"type":"text","text":"In vitro and animal studies characterise pharmacology, toxicology and a first estimate of a safe starting dose. Nothing here proves efficacy in humans; it justifies the risk of a first-in-human study."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Phase I: is it safe, and how does the body handle it?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Question: ","marks":[{"type":"bold"}]},{"type":"text","text":"safety, tolerability, pharmacokinetics (PK) and pharmacodynamics (PD)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Participants: ","marks":[{"type":"bold"}]},{"type":"text","text":"usually 20–100 healthy volunteers; in oncology, patients with the disease."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Typical designs: ","marks":[{"type":"bold"}]},{"type":"text","text":"single ascending dose (SAD) and multiple ascending dose (MAD) cohorts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Key outputs: ","marks":[{"type":"bold"}]},{"type":"text","text":"half-life, exposure (AUC, Cmax), dose-limiting toxicities and a dose range for Phase II."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Phase II: is there a signal of efficacy?"}]},{"type":"paragraph","content":[{"type":"text","text":"Phase II studies enrol patients with the target condition, often a few hundred, to explore whether the drug has the intended effect and which dose offers the best balance of benefit and harm. Many use surrogate or intermediate endpoints (for example blood pressure or tumour response) because they respond faster than hard outcomes."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Phase III: does it work in a confirmatory setting?"}]},{"type":"paragraph","content":[{"type":"text","text":"Phase III trials are usually large, randomised and controlled, frequently double-blind, and are designed to confirm efficacy and characterise safety in a population closer to real practice. Their pre-specified primary endpoint and sample size calculation are what regulators scrutinise most."}]},{"type":"callout","attrs":{"variant":"key-point"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Attrition is the norm. ","marks":[{"type":"bold"}]},{"type":"text","text":"In a large analysis of trials run between 2000 and 2015, the overall probability that a programme entering Phase I would reach approval was about 14%, with wide variation by therapeutic area — oncology was the lowest, at roughly 3% "},{"type":"citation","attrs":{"refs":"2"}},{"type":"text","text":"."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Regulatory review"}]},{"type":"paragraph","content":[{"type":"text","text":"The sponsor compiles the evidence into a marketing application — an NDA or BLA at the FDA, a marketing authorisation application at the EMA, or a registration dossier at ANVISA in Brazil — and the regulator weighs benefit against risk for the proposed indication "},{"type":"citation","attrs":{"refs":"3"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Phase IV: what happens after approval?"}]},{"type":"paragraph","content":[{"type":"text","text":"Approval is not the end of evidence generation. Post-marketing studies and pharmacovigilance systems detect rare or delayed adverse events that trials of a few thousand participants cannot capture, evaluate long-term outcomes and study populations that were excluded from pivotal trials."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Summary"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Phase"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Main question"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Typical size"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Typical design"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"I"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Safety, PK/PD, dose range"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"20–100"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Dose escalation, often open-label"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"II"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Efficacy signal, dose selection"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"100–300"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Randomised, sometimes placebo-controlled"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"III"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Confirm efficacy and safety"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Hundreds to thousands"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Randomised, controlled, often blinded"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"IV"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Long-term and rare effects"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Thousands or more"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Observational studies, registries, pharmacovigilance"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"My takeaways"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each phase answers a different question, so a \"positive\" Phase II result is not evidence of clinical benefit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Look for the primary endpoint and the population before looking at the results."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Safety knowledge keeps growing after approval; pharmacists are part of that system through adverse event reporting."}]}]}]}]}'::jsonb, 'published', false, 'en', (select c.id from public.categories c where c.slug = 'concept-explainer'), 'What Phase I, II, III and IV clinical trials are designed to answer, typical sample sizes and why most investigational drugs fail.', '2026-06-02T09:00:00Z', (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
on conflict (slug) do nothing;

values ('Understanding Hazard Ratio in Clinical Trials', 'understanding-hazard-ratio-in-clinical-trials', 'What an HR of 0.75 does — and does not — tell you', 'Hazard ratios dominate time-to-event results in oncology and cardiology. This note explains what the number means, the proportional hazards assumption behind it and the most common misreadings.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why this matters"}]},{"type":"paragraph","content":[{"type":"text","text":"When a trial measures "},{"type":"text","text":"time","marks":[{"type":"italic"}]},{"type":"text","text":" until an event — death, disease progression, hospitalisation — the headline result is usually a hazard ratio (HR). It appears in the abstract, in press releases and in medical information letters, so misreading it propagates quickly."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The definition"}]},{"type":"paragraph","content":[{"type":"text","text":"The hazard is the instantaneous rate at which events occur among people who have not yet had the event. The hazard ratio compares that rate between two groups:"}]},{"type":"blockMath","attrs":{"latex":"\\mathrm{HR} = \\frac{h_{\\text{treatment}}(t)}{h_{\\text{control}}(t)}"}},{"type":"paragraph","content":[{"type":"text","text":"Under the proportional hazards assumption this ratio is constant over time, which is what the Cox model estimates "},{"type":"citation","attrs":{"refs":"2"}},{"type":"text","text":". An HR below 1 favours the treatment when the event is harmful; an HR of exactly 1 means no difference."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Understanding the numbers"}]},{"type":"paragraph","content":[{"type":"text","text":"Take an illustrative result: "},{"type":"inlineMath","attrs":{"latex":"\\mathrm{HR} = 0.75"}},{"type":"text","text":", 95% CI 0.62 to 0.91. A reasonable reading is: "},{"type":"text","text":"at any given moment during follow-up, patients on treatment experienced the event at about three quarters of the rate of patients on control.","marks":[{"type":"italic"}]}]},{"type":"callout","attrs":{"variant":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Common misreading: ","marks":[{"type":"bold"}]},{"type":"text","text":"“HR 0.75 means 25% fewer patients had the event.” The HR compares rates over time, not cumulative proportions at a fixed time point. The difference in the proportion of patients with an event depends on the baseline risk and the length of follow-up "},{"type":"citation","attrs":{"refs":"1"}},{"type":"text","text":"."}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Reading the confidence interval"}]},{"type":"paragraph","content":[{"type":"text","text":"Because the whole 95% confidence interval in the example lies below 1, the data are compatible with a benefit ranging from modest (0.91) to substantial (0.62). A wide interval crossing 1 means the data are compatible with benefit, no effect and harm."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Statistical analysis"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kaplan–Meier curves ","marks":[{"type":"bold"}]},{"type":"text","text":"show the estimated proportion of patients event-free over time in each group."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The log-rank test ","marks":[{"type":"bold"}]},{"type":"text","text":"tests whether the curves differ; it does not estimate the size of the difference."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Cox proportional hazards model ","marks":[{"type":"bold"}]},{"type":"text","text":"estimates the HR and can adjust for covariates."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Limitations"}]},{"type":"paragraph","content":[{"type":"text","text":"If the curves cross or separate only late — common with immunotherapies — hazards are not proportional and a single HR averages over very different periods. Alternatives such as the difference in restricted mean survival time (RMST) express the effect in units of time and do not rely on proportional hazards "},{"type":"citation","attrs":{"refs":"3"}},{"type":"text","text":"."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Always ask: proportional over what period, in which population, and what was the absolute risk in the control group?"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"My takeaways"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Translate the HR into “rate at any moment”, not “percentage fewer events”."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the Kaplan–Meier curves before trusting a single summary number."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pair the HR with absolute measures (event rates, RMST) when communicating results."}]}]}]}]}'::jsonb, 'published', true, 'en', (select c.id from public.categories c where c.slug = 'concept-explainer'), 'A clear explanation of hazard ratios in clinical trials: definition, proportional hazards, confidence intervals and common misinterpretations.', '2026-06-23T09:00:00Z', (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
on conflict (slug) do nothing;

values ('What Does a 95% Confidence Interval Actually Mean?', 'what-does-a-95-confidence-interval-actually-mean', 'A property of the method, not a probability about one interval', 'Confidence intervals are the most useful number in a results table and one of the most misunderstood. Here is the correct interpretation, how they are built and how to use them in practice.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why this matters"}]},{"type":"paragraph","content":[{"type":"text","text":"A point estimate on its own hides uncertainty. The confidence interval (CI) shows the range of effect sizes that are reasonably compatible with the data, which is exactly what a clinician or a medical affairs team needs to judge whether a result matters."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The correct interpretation"}]},{"type":"paragraph","content":[{"type":"text","text":"If we repeated the same study many times and computed a 95% CI each time, about 95% of those intervals would contain the true value. The 95% describes the long-run behaviour of the "},{"type":"text","text":"procedure","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"citation","attrs":{"refs":"1"}},{"type":"text","text":"."}]},{"type":"callout","attrs":{"variant":"warning"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Not quite right: ","marks":[{"type":"bold"}]},{"type":"text","text":"“There is a 95% probability that the true value lies in this interval.” In the frequentist framework the true value is fixed; a specific interval either contains it or does not."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How it is built"}]},{"type":"paragraph","content":[{"type":"text","text":"For a mean with an approximately normal sampling distribution:"}]},{"type":"blockMath","attrs":{"latex":"\\bar{x} \\pm 1.96 \\times \\frac{s}{\\sqrt{n}}"}},{"type":"paragraph","content":[{"type":"text","text":"Ratio measures such as risk ratios, odds ratios and hazard ratios are calculated on the log scale and back-transformed, which is why their intervals are asymmetric around the point estimate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Understanding the numbers"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Illustrative result"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Reading"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Mean difference −4.1 mmHg (95% CI −6.0 to −2.2)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Consistent with a reduction between 2 and 6 mmHg."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Risk ratio 0.90 (95% CI 0.78 to 1.04)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Compatible with a 22% reduction or a 4% increase."}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Odds ratio 1.8 (95% CI 1.1 to 2.9)"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Compatible with modest to large increases in odds."}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Relation to p-values"}]},{"type":"paragraph","content":[{"type":"text","text":"For a two-sided test at the 5% level, a 95% CI that excludes the null value (0 for differences, 1 for ratios) corresponds to p < 0.05. The interval is more informative because it shows magnitude and precision; it is even possible to approximate the CI from a reported p-value "},{"type":"citation","attrs":{"refs":"2"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Limitations"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A CI only reflects random error. It says nothing about bias from confounding, poor randomisation or missing data."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wide intervals usually mean small samples or few events — absence of evidence, not evidence of absence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Statistical significance does not equal clinical relevance; compare the interval with a minimal clinically important difference."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"My takeaways"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Read the interval before the p-value."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ask whether both ends of the interval would change practice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Remember that “95%” describes the method, not this particular interval."}]}]}]}]}'::jsonb, 'published', false, 'en', (select c.id from public.categories c where c.slug = 'concept-explainer'), 'The correct interpretation of a 95% confidence interval, how it is calculated and how it relates to p-values and clinical significance.', '2026-07-14T09:00:00Z', (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
on conflict (slug) do nothing;

values ('Relative Risk vs Absolute Risk', 'relative-risk-vs-absolute-risk', 'Why “50% lower risk” can mean one patient in a hundred', 'The same trial result can sound dramatic or modest depending on how it is framed. A worked example of relative risk reduction, absolute risk reduction and number needed to treat.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why this matters"}]},{"type":"paragraph","content":[{"type":"text","text":"Relative measures are stable across populations and useful for modelling, but on their own they exaggerate perceived benefit. Absolute measures tell a patient — or a payer — how much difference a treatment actually makes "},{"type":"citation","attrs":{"refs":"1"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The definitions"}]},{"type":"paragraph","content":[{"type":"text","text":"With CER the control event rate and EER the experimental event rate:"}]},{"type":"blockMath","attrs":{"latex":"\\mathrm{RR} = \\frac{\\mathrm{EER}}{\\mathrm{CER}} \\qquad \\mathrm{ARR} = \\mathrm{CER} - \\mathrm{EER} \\qquad \\mathrm{NNT} = \\frac{1}{\\mathrm{ARR}}"}},{"type":"paragraph","content":[{"type":"text","text":"The relative risk reduction is "},{"type":"inlineMath","attrs":{"latex":"\\mathrm{RRR} = 1 - \\mathrm{RR}"}},{"type":"text","text":". The number needed to treat was proposed precisely to make trial results clinically interpretable "},{"type":"citation","attrs":{"refs":"2"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Understanding the numbers"}]},{"type":"paragraph","content":[{"type":"text","text":"An illustrative example with the same relative effect in two populations:"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Population"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Control risk"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Treated risk"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"RRR"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"ARR"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"NNT"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Low baseline risk"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"2%"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"1%"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"50%"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"1 percentage point"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"100"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"High baseline risk"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"20%"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"10%"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"50%"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"10 percentage points"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"10"}]}]}]}]},{"type":"callout","attrs":{"variant":"key-point"},"content":[{"type":"paragraph","content":[{"type":"text","text":"The relative risk reduction is identical, but treating 100 low-risk patients prevents one event, while treating 10 high-risk patients prevents one. "},{"type":"text","text":"Baseline risk drives absolute benefit.","marks":[{"type":"bold"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Implications for medical affairs"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Present relative and absolute effects together, with the time horizon (for example “over 3 years”)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Report harms in the same format as benefits — number needed to harm alongside NNT."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use natural frequencies (“1 in 100”) when communicating with patients."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Limitations"}]},{"type":"paragraph","content":[{"type":"text","text":"NNT depends on baseline risk and follow-up duration, so it cannot be compared across trials with different populations or time frames without care. It also has awkward confidence intervals when the effect is not statistically significant."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"My takeaways"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When you see a relative reduction, look for the control event rate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Translate results into NNT over a defined period."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Balanced communication shows both absolute benefit and absolute harm."}]}]}]}]}'::jsonb, 'published', false, 'en', (select c.id from public.categories c where c.slug = 'concept-explainer'), 'Relative risk, absolute risk reduction and number needed to treat explained with a worked example and implications for medical communication.', '2026-08-04T09:00:00Z', (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
on conflict (slug) do nothing;

values ('How to Read a Clinical Research Paper', 'how-to-read-a-clinical-research-paper', 'A structured checklist I use for every study', 'Start with the question, not the conclusion. A section-by-section method for appraising clinical studies, from PICO to limitations, using the structure of a CONSORT-compliant report.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why this study matters"}]},{"type":"paragraph","content":[{"type":"text","text":"Before reading results, decide why the paper deserves your time: does it address a clinically relevant question, is it likely to change practice, and who funded it? Greenhalgh’s advice still holds: first work out what the paper is about "},{"type":"citation","attrs":{"refs":"1"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Research Question"}]},{"type":"paragraph","content":[{"type":"text","text":"Frame the question with PICO:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"P","marks":[{"type":"bold"}]},{"type":"text","text":"opulation — who was studied?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"I","marks":[{"type":"bold"}]},{"type":"text","text":"ntervention — what was done?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"C","marks":[{"type":"bold"}]},{"type":"text","text":"omparator — compared with what (placebo, standard of care)?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"O","marks":[{"type":"bold"}]},{"type":"text","text":"utcome — what was measured, and when?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Study Design"}]},{"type":"paragraph","content":[{"type":"text","text":"Identify the design (randomised trial, cohort, case-control, cross-sectional) and check whether it can answer the question. For randomised trials, reports should follow CONSORT "},{"type":"citation","attrs":{"refs":"2"}},{"type":"text","text":", which makes randomisation, allocation concealment and blinding easy to locate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Population"}]},{"type":"paragraph","content":[{"type":"text","text":"Read the inclusion and exclusion criteria and the baseline characteristics table. Would your patients have been eligible? Trials often exclude older adults, pregnant people and patients with multiple comorbidities."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Intervention"}]},{"type":"paragraph","content":[{"type":"text","text":"Note dose, duration, route and co-interventions. Is the comparator a fair representation of current care?"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Endpoints"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Is the primary endpoint clinically meaningful or a surrogate?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Was it pre-specified (check the trial registration)?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Composite endpoints: which component drives the result?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Results"}]},{"type":"paragraph","content":[{"type":"text","text":"Look at the flow diagram first: how many participants were randomised, analysed and lost to follow-up?"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Understanding the Numbers"}]},{"type":"paragraph","content":[{"type":"text","text":"Extract the effect estimate with its confidence interval, the control event rate and an absolute measure (ARR or NNT). A relative reduction without the baseline risk is incomplete."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Statistical Analysis"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Intention-to-treat or per-protocol? For superiority trials, ITT is the primary analysis."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Was the sample size calculation based on a plausible effect size?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Were subgroup analyses pre-specified, and is there a formal interaction test?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Limitations"}]},{"type":"paragraph","content":[{"type":"text","text":"Read the authors’ limitations, then add your own: risk of bias, generalisability, follow-up length, funding and conflicts of interest."}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Tools such as the Cochrane Risk of Bias tool (RoB 2) for randomised trials provide a structured way to judge internal validity."}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"My Takeaways"}]},{"type":"paragraph","content":[{"type":"text","text":"I finish every appraisal with three sentences:"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What did the study find, in absolute terms?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"How confident am I in the result, and why?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Would it change what I recommend to a patient or a healthcare professional?"}]}]}]}]}'::jsonb, 'published', false, 'en', (select c.id from public.categories c where c.slug = 'guide'), 'A practical, section-by-section method to critically appraise a clinical research paper: question, design, population, endpoints, results and limitations.', '2026-09-01T09:00:00Z', (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
on conflict (slug) do nothing;

