values ('Clinical Trial Dashboard', 'clinical-trial-dashboard', 'An exploratory dashboard of registered clinical trials, filtered by phase, condition and status, built from public registry data.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Goal"}]},{"type":"paragraph","content":[{"type":"text","text":"Practise working with real registry data and describe the trial landscape for a therapeutic area."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scope"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Download study records from the public ClinicalTrials.gov API."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clean phases, statuses and enrolment figures."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Visualise trials by phase, sponsor type and recruitment status."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Status"}]},{"type":"paragraph","content":[{"type":"text","text":"In progress. ","marks":[{"type":"bold"}]},{"type":"text","text":"Data extraction and cleaning are done; the visual layer is being built."}]}]}'::jsonb, 'published', 'in_progress', array['Python', 'pandas', 'Plotly', 'ClinicalTrials.gov API']::text[], '2026-03-01', null, true, 1, now(), (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
on conflict (slug) do nothing;
values ('Power BI Health Data Project', 'power-bi-health-data-project', 'A Power BI report exploring public health indicators, focused on data modelling, DAX measures and clear visual communication.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Goal"}]},{"type":"paragraph","content":[{"type":"text","text":"Build an end-to-end report: import, model, measure and present health indicators."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What I practised"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Star-schema data modelling"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Time-intelligence DAX measures"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accessible chart design"}]}]}]}]}'::jsonb, 'published', 'completed', array['Power BI', 'DAX', 'Power Query']::text[], '2025-09-01', '2025-12-15', false, 2, now(), (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
on conflict (slug) do nothing;
values ('Biostatistics Learning Notes', 'biostatistics-learning-notes', 'Reproducible notes and code for core biostatistics methods used in clinical research, written in R with Quarto.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Goal"}]},{"type":"paragraph","content":[{"type":"text","text":"Turn each statistics concept from the blog into a runnable, reproducible example."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Planned chapters"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confidence intervals by simulation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kaplan–Meier and the log-rank test"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cox regression and proportional hazards"}]}]}]}]}'::jsonb, 'published', 'in_progress', array['R', 'Quarto', 'tidyverse']::text[], '2026-01-10', null, false, 3, now(), (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
on conflict (slug) do nothing;
values ('Research Data Analysis', 'research-data-analysis', 'Planned analysis of an open clinical dataset, from protocol-style analysis plan to a short written report.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Goal"}]},{"type":"paragraph","content":[{"type":"text","text":"Write a statistical analysis plan before touching the data, then follow it and report deviations."}]}]}'::jsonb, 'published', 'planned', array['R', 'survival', 'ggplot2']::text[], null, null, false, 4, now(), (select p.id from public.profiles p where p.role = 'admin' and p.is_active order by p.created_at limit 1))
