-- Plain-text projection and reading time (the app recomputes both on every save).
update public.articles set content_text = coalesce((select string_agg(v #>> '{}', ' ') from jsonb_path_query(content, 'strict $.**.text') as v), '') where content_text = '';
update public.projects set content_text = coalesce((select string_agg(v #>> '{}', ' ') from jsonb_path_query(content, 'strict $.**.text') as v), '') where content_text = '';
update public.articles set reading_time = greatest(1, ceil(coalesce(array_length(regexp_split_to_array(btrim(content_text), '\s+'), 1), 0) / 220.0)::integer) where content_text <> '';

commit;
